import {createLeafTextures} from '../src/leaf.js';
import {createCoffeeStudy} from '../src/coffee.js';
function start(){const api=window.__plantStudy;if(!api?.study)return;const coffee=createCoffeeStudy({textures:createLeafTextures({coffee:true,size:1024})});api.mount(coffee,{id:'02',view:{target:[0,1.4,0],yaw:.45,pitch:1.40,distance:7.3,nearTarget:[0,1.7,0],nearDistance:2.6},background:0x303b2d,environmentIntensity:.45,ambient:1.1,rim:1.0,time:27,dof:0});document.querySelector('.edition').textContent='STUDY 02 · STRUCTURE R03';document.querySelector('.brand small').textContent='VEGETATION · FIELD NOTES 02';document.querySelector('#reference-macro').hidden=true;document.querySelector('#source-dialog').innerHTML='<button id="coffee-source-close" class="close">关闭</button><h2>根与枝的共同生长结构</h2><p>本例继承植被母体 1.14 的逐轴出生与父子附着原则，独立实现路径尖端推进、半径增长、对生叶展开和根系分叉。并未取得参考视频作者的原 Houdini 工程，当前不标为原例复刻。</p><p>67 条轴，含 46 条根轴；节点必须等母轴尖端抵达连接位置后才出生。叶片附着于叶柄正在生长的尖端。</p><p>画面和物种细节仍待验证；30 秒是演示时间，不代表咖啡树的实际物候。</p>';document.querySelector('#coffee-source-close').onclick=()=>document.querySelector('#source-dialog').close();document.title='植被自习02 · 根与咖啡生长 · 结构候选';document.querySelector('#cases').innerHTML='<button class="active">02 根与咖啡生长</button>';document.querySelector('#title').textContent='从一粒种子开始';document.querySelector('#subtitle').textContent='胚根 → 节间 → 对生叶 → 花与果';document.querySelector('.scene-caption').classList.add('dark');document.querySelector('aside h2').textContent='根与枝，共用一张生长图';document.querySelector('aside > .muted').textContent='每个根尖沿自己的路径伸长。侧根等母根抵达分叉点后才出生；叶片展开时仍附着在生长中的叶柄上。演示时间不是实际物候天数。';document.querySelector('.segmented').hidden=true;document.querySelector('#leaf-parameters').hidden=true;const common=document.createElement('section');common.className='parameters';for(const id of ['light','exposure','dof'])common.append(document.querySelector('#'+id).closest('label'));document.querySelector('#leaf-parameters').after(common);const cut=document.createElement('label');cut.className='check';cut.innerHTML='<input type="checkbox" id="root-cut">地下结构剖面';document.querySelector('.timeline').before(cut);document.querySelector('#root-cut').onchange=e=>{coffee.setRootCut(e.target.checked);document.querySelector('#reset').click();api.invalidate();};document.querySelector('#evidence-summary').textContent='67条轴，包含46条根轴。九阶段父子连接检查通过；当前仍是视觉未验收的结构候选。未取得视频作者原Houdini节点工程。';document.querySelector('.evidence b').textContent='连接与出生顺序已检查';api.params.light=315;document.querySelector('#light').value=315;document.querySelector('#light').dispatchEvent(new Event('input'));api.setTime(27);document.querySelector('#reset').click();api.coffeeReady=true;}
window.addEventListener('vegetation-study-ready',start,{once:true});if(window.__plantStudy?.study)start();
